"use client"

import * as React from "react"
import { createPortal } from "react-dom"

// useLayoutEffect on the server logs a warning; fall back to useEffect there. The
// shadow root only exists on the client, so the effect is a no-op during SSR.
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

// Drop every `:has()` style rule from a constructed sheet (recursing into
// @media/@supports/@layer blocks). The grid's own markup uses no `has-*`
// variants, so these rules never style it, but Blink would still re-run their
// invalidation against the grid subtree on each per-scroll mutation.
function stripHasRules(owner: CSSStyleSheet | CSSGroupingRule) {
  const rules = owner.cssRules
  if (!rules) return
  for (let index = rules.length - 1; index >= 0; index--) {
    const rule = rules[index]
    if ((rule as CSSStyleRule).selectorText?.includes(":has(")) {
      try {
        owner.deleteRule(index)
      } catch {
        // ignore a rule that cannot be removed
      }
    } else if ((rule as CSSGroupingRule).cssRules?.length) {
      stripHasRules(rule as CSSGroupingRule)
    }
  }
}

let sharedSheets: CSSStyleSheet[] | null = null

function getSharedSheets(): CSSStyleSheet[] {
  if (sharedSheets) return sharedSheets
  const nextSheets: CSSStyleSheet[] = []
  for (const stylesheet of Array.from(document.styleSheets)) {
    let rules: CSSRuleList
    try {
      rules = stylesheet.cssRules
    } catch {
      continue
    }
    let text = ""
    for (const rule of Array.from(rules)) text += rule.cssText + "\n"
    try {
      const sheet = new CSSStyleSheet()
      sheet.replaceSync(text)
      stripHasRules(sheet)
      nextSheets.push(sheet)
    } catch {
      // skip any sheet that cannot be reconstructed
    }
  }
  sharedSheets = nextSheets
  return nextSheets
}

function ShadowScope({
  className,
  style,
  children,
}: {
  className?: string
  style?: React.CSSProperties
  children: React.ReactNode
}) {
  const hostRef = React.useRef<HTMLDivElement>(null)
  const [root, setRoot] = React.useState<ShadowRoot | null>(null)

  useIsomorphicLayoutEffect(() => {
    const host = hostRef.current
    if (!host) return
    const shadowRoot = host.shadowRoot ?? host.attachShadow({ mode: "open" })
    try {
      shadowRoot.adoptedStyleSheets = getSharedSheets()
    } catch {
      for (const node of Array.from(
        document.querySelectorAll('style, link[rel="stylesheet"]')
      )) {
        try {
          shadowRoot.appendChild(node.cloneNode(true))
        } catch {
          // ignore a node that cannot be cloned
        }
      }
    }
    setRoot(shadowRoot)
  }, [])

  return (
    <div ref={hostRef} className={className} style={style}>
      {root ? createPortal(children, root) : null}
    </div>
  )
}

export function ScrollerShell({
  isolate,
  className,
  style,
  children,
}: {
  isolate: boolean
  className?: string
  style?: React.CSSProperties
  children: React.ReactNode
}) {
  if (isolate) {
    return (
      <ShadowScope className={className} style={style}>
        {children}
      </ShadowScope>
    )
  }
  return (
    <div className={className} style={style}>
      {children}
    </div>
  )
}

import { resolveXlsxSheetChange, type XlsxSheetMeta } from "@/lib/xlsx-workbook"

export interface PublicXlsxCellRef {
  sheet: number
  row: number
  col: number
}

export interface InternalXlsxCellRef {
  sheetIndex: number
  rowIndex: number
  columnIndex: number
}

export type PendingXlsxScrollTarget = InternalXlsxCellRef & {
  behavior: ScrollBehavior
}

export type XlsxScrollRequest = PendingXlsxScrollTarget & {
  nonce: number
}

export interface ResolvedXlsxScrollTarget {
  sheetIndex: number
  request: PendingXlsxScrollTarget
  changed: boolean
}

export function toInternalCellRef(
  cellRef: PublicXlsxCellRef | null | undefined
): InternalXlsxCellRef | null {
  if (!isValidPublicCellRef(cellRef)) return null
  return {
    sheetIndex: cellRef.sheet,
    rowIndex: cellRef.row,
    columnIndex: cellRef.col,
  }
}

export function isValidPublicCellRef(
  cellRef: PublicXlsxCellRef | null | undefined
): cellRef is PublicXlsxCellRef {
  return (
    cellRef != null &&
    Number.isSafeInteger(cellRef.sheet) &&
    Number.isSafeInteger(cellRef.row) &&
    Number.isSafeInteger(cellRef.col) &&
    cellRef.sheet >= 0 &&
    cellRef.row >= 0 &&
    cellRef.col >= 0
  )
}

export function isValidLoadedScrollTarget(
  target: InternalXlsxCellRef,
  sheets: XlsxSheetMeta[]
): boolean {
  const sheet = sheets[target.sheetIndex]
  const rowCount = normalizeSheetDimension(sheet?.rowCount)
  const columnCount = normalizeSheetDimension(sheet?.columnCount)
  return (
    !!sheet &&
    Number.isSafeInteger(target.rowIndex) &&
    Number.isSafeInteger(target.columnIndex) &&
    target.rowIndex >= 0 &&
    target.columnIndex >= 0 &&
    target.rowIndex < rowCount &&
    target.columnIndex < columnCount
  )
}

export function resolveLoadedScrollTarget({
  activeSheetIndex,
  target,
  sheets,
}: {
  activeSheetIndex: number
  target: PendingXlsxScrollTarget
  sheets: XlsxSheetMeta[]
}): ResolvedXlsxScrollTarget | null {
  if (!isValidLoadedScrollTarget(target, sheets)) return null

  const change = resolveXlsxSheetChange({
    activeSheet: activeSheetIndex,
    requestedSheet: target.sheetIndex,
    sheetCount: sheets.length,
  })
  if (!change.accepted) return null

  return {
    sheetIndex: change.sheetIndex,
    request: target,
    changed: change.changed,
  }
}

function normalizeSheetDimension(value: number | undefined) {
  return value != null && Number.isFinite(value) && value > 0
    ? Math.floor(value)
    : 0
}

// Web Worker that owns the SheetJS parse so it never blocks the UI thread.
// @e965/xlsx is a patched, zero-dependency republish of SheetJS. The main thread
// transfers the file bytes in; the worker parses the workbook and flattens it
// into sparse compact sheets before transferring typed-array buffers back.
import * as XLSX from "@e965/xlsx"

import {
  compactWorkbookTransferBuffers,
  flattenSheetJsWorkbook,
} from "@/lib/xlsx-sheetjs-flattener"
import {
  XlsxWorkerError,
  type XlsxWorkerRequest,
  type XlsxWorkerResponse,
} from "@/lib/xlsx-worker-protocol"

// Cast the worker global to `Worker` so `onmessage`/`postMessage` type-check
// under the DOM lib without pulling in the conflicting "webworker" lib.
const ctx = self as unknown as Worker

ctx.onmessage = (event: MessageEvent<XlsxWorkerRequest>) => {
  try {
    if (event.data.type !== "parse_workbook") {
      throw new XlsxWorkerError(
        "parse_failed",
        "Unsupported spreadsheet request"
      )
    }

    // cellDates formats dates as text in `.w`; we never need styles or formulae.
    const workbook = XLSX.read(event.data.buffer, {
      type: "array",
      cellDates: true,
    })
    const sheets = flattenSheetJsWorkbook(workbook)
    const response: XlsxWorkerResponse = { type: "workbook", sheets }
    ctx.postMessage(response, compactWorkbookTransferBuffers(sheets))
  } catch (error) {
    const response: XlsxWorkerResponse = {
      type: "error",
      code: error instanceof XlsxWorkerError ? error.code : "parse_failed",
      message:
        error instanceof Error ? error.message : "Failed to parse spreadsheet",
    }
    ctx.postMessage(response)
  }
}
